import{_ as e,c as a,o as n,ag as s}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Dashboard and Monitoring","description":"Real-time monitoring, statistics, and alerts","frontmatter":{"title":"Dashboard and Monitoring","description":"Real-time monitoring, statistics, and alerts"},"headers":[],"relativePath":"engine/dashboard_and_monitoring.md","filePath":"engine/dashboard_and_monitoring.md","lastUpdated":1788476353000}'),r={name:"engine/dashboard_and_monitoring.md"};function o(i,t,d,l,h,c){return n(),a("div",null,t[0]||(t[0]=[s('<h1 id="dashboard-and-monitoring" tabindex="-1">Dashboard and Monitoring <a class="header-anchor" href="#dashboard-and-monitoring" aria-label="Permalink to &quot;Dashboard and Monitoring&quot;">​</a></h1><p>The Dashboard is the first view you see after logging into the Administrator. It provides a live overview of every deployed channel, covering running state, message throughput, and connection activity, with quick access to start, stop, and manage them.</p><h2 id="dashboard-table" tabindex="-1">Dashboard table <a class="header-anchor" href="#dashboard-table" aria-label="Permalink to &quot;Dashboard table&quot;">​</a></h2><p>The main section of the Dashboard is a table listing all deployed channels, organized under their channel groups. Each row can be expanded to reveal individual connector-level statistics.</p><h3 id="dashboard-columns" tabindex="-1">Dashboard columns <a class="header-anchor" href="#dashboard-columns" aria-label="Permalink to &quot;Dashboard columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>The channel&#39;s current state. See <a href="#channel-statuses">Channel Statuses</a> below for the full list.</td></tr><tr><td><strong>Name</strong></td><td>The channel (or group) name, along with any assigned tags displayed as colored labels</td></tr><tr><td><strong>Rev Δ</strong></td><td>How many times the channel has been saved since it was last deployed. A non-zero value means there are undeployed changes. Also highlighted if linked code templates have changed.</td></tr><tr><td><strong>Last Deployed</strong></td><td>When the channel was most recently deployed. Highlighted if within the last two minutes.</td></tr><tr><td><strong>Received</strong></td><td>Messages received and accepted by the source connector</td></tr><tr><td><strong>Filtered</strong></td><td>Messages rejected by filters on the source or any destination</td></tr><tr><td><strong>Queued</strong></td><td>Messages currently sitting in a destination queue. Highlighted when greater than zero.</td></tr><tr><td><strong>Sent</strong></td><td>Messages successfully dispatched by all destination connectors</td></tr><tr><td><strong>Errored</strong></td><td>Messages that encountered an error anywhere in the channel. Highlighted when greater than zero.</td></tr><tr><td><strong>Connection</strong></td><td>Live activity indicator for the channel or connector. See <a href="#connection-statuses">Connection Statuses</a> below.</td></tr></tbody></table><h3 id="channel-statuses" tabindex="-1">Channel statuses <a class="header-anchor" href="#channel-statuses" aria-label="Permalink to &quot;Channel statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Deploying</strong></td><td>The channel is being deployed. If it stays in this state, the deploy script may be running long.</td></tr><tr><td><strong>Undeploying</strong></td><td>The channel is being undeployed. A long stay here suggests a slow shutdown script.</td></tr><tr><td><strong>Starting</strong></td><td>The channel is starting up, possibly recovering unfinished messages.</td></tr><tr><td><strong>Started</strong></td><td>The channel is running. A green icon means all connectors are active; an orange icon means at least one connector underneath is not started.</td></tr><tr><td><strong>Pausing</strong></td><td>The source connector is shutting down while in-flight messages finish processing.</td></tr><tr><td><strong>Paused</strong></td><td>The source connector is stopped, so no new messages will arrive. However, queued destination messages may still flow outbound. You can still manually send or reprocess messages.</td></tr><tr><td><strong>Stopping</strong></td><td>The channel is shutting down gracefully. In-flight messages will complete before the channel fully stops.</td></tr><tr><td><strong>Stopped</strong></td><td>The channel is not running. No messages will be received or sent.</td></tr></tbody></table><p>When a row represents a <strong>group</strong> rather than a single channel, the status reflects the combined state of all channels in that group. If channels have mixed states, the group shows <strong>Mixed</strong>.</p><h3 id="connection-statuses" tabindex="-1">Connection statuses <a class="header-anchor" href="#connection-statuses" aria-label="Permalink to &quot;Connection statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Idle</strong></td><td>The connector is not actively processing</td></tr><tr><td><strong>Reading</strong></td><td>The source connector is reading inbound data (typical for polling connectors)</td></tr><tr><td><strong>Writing</strong></td><td>The destination connector is dispatching a message outbound</td></tr><tr><td><strong>Polling</strong></td><td>The source connector is actively polling for new data</td></tr><tr><td><strong>Receiving</strong></td><td>The source connector is receiving a message from an external system</td></tr><tr><td><strong>Sending</strong></td><td>The destination connector is transmitting outbound</td></tr><tr><td><strong>Waiting For Response</strong></td><td>The destination connector has sent a message and is awaiting a reply</td></tr><tr><td><strong>Connected</strong></td><td>The source connector has one or more active client connections. Typically includes a count of connected clients.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When a source connector has active client connections, the connection count is shown in parentheses after the status. If the connector has reached its maximum allowed connections, the count appears in red. Existing clients can still send, but no new connections will be accepted until one disconnects.</p></div><h2 id="dashboard-tasks" tabindex="-1">Dashboard tasks <a class="header-anchor" href="#dashboard-tasks" aria-label="Permalink to &quot;Dashboard tasks&quot;">​</a></h2><p>The task panel on the left provides these operations when the Dashboard is active:</p><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Manually reload the dashboard table. The dashboard also auto-refreshes at an interval configured in Administrator settings.</td></tr><tr><td><strong>Send Message</strong></td><td>Opens a dialog where you can type or load a message, choose which destinations to include, and optionally inject source map variables. Click <strong>Process Message</strong> to submit it to the selected channel.</td></tr><tr><td><strong>View Messages</strong></td><td>Opens the Message Browser for the selected channel</td></tr><tr><td><strong>Remove All Messages</strong></td><td>Deletes all stored messages and attachments for the selected channel(s). Requires typing <code>REMOVEALL</code> as a safety confirmation.</td></tr><tr><td><strong>Clear Statistics</strong></td><td>Resets the current statistics counters to zero for the selected channel(s) and connector(s). Only available when viewing Current Statistics.</td></tr><tr><td><strong>Start</strong></td><td>Starts or resumes the selected channel(s). Channel dependency rules may apply.</td></tr><tr><td><strong>Pause</strong></td><td>Pauses the selected channel(s) by stopping the source connector. Equivalent to halting inbound traffic while letting queued messages drain.</td></tr><tr><td><strong>Stop</strong></td><td>Gracefully stops the selected channel(s), allowing in-flight messages to finish first.</td></tr><tr><td><strong>Halt</strong></td><td>Force-stops the selected channel(s) immediately. Any messages mid-processing will be left incomplete and recovered on the next start.</td></tr><tr><td><strong>Undeploy Channel</strong></td><td>Removes the channel from the deployed set. The channel is gracefully stopped first, then disappears from the Dashboard (it remains available in the Channels view).</td></tr></tbody></table><h2 id="filtering-the-dashboard" tabindex="-1">Filtering the Dashboard <a class="header-anchor" href="#filtering-the-dashboard" aria-label="Permalink to &quot;Filtering the Dashboard&quot;">​</a></h2><h3 id="by-channel-name-or-tag" tabindex="-1">By channel name or tag <a class="header-anchor" href="#by-channel-name-or-tag" aria-label="Permalink to &quot;By channel name or tag&quot;">​</a></h3><p>The <strong>Filter</strong> field at the bottom of the dashboard lets you narrow the table to specific channels:</p><ul><li>Start typing to see auto-complete suggestions for both tags and channel names</li><li>Press Enter or double-click to apply a filter</li><li>Tags show with a tag icon, channels with a channel icon</li><li>You can stack multiple filters (tags and/or names). When multiple tags are applied, only channels matching <strong>all</strong> of them appear.</li><li>Click the X next to a filter chip to remove it, or click the red X to clear everything</li></ul><h3 id="by-group-view" tabindex="-1">By group view <a class="header-anchor" href="#by-group-view" aria-label="Permalink to &quot;By group view&quot;">​</a></h3><p>Toggle the control icons in the bottom-right corner of the table to switch between showing channels organized under groups or as a flat list.</p><h3 id="tag-display" tabindex="-1">Tag display <a class="header-anchor" href="#tag-display" aria-label="Permalink to &quot;Tag display&quot;">​</a></h3><p>Tags appear as colored text bubbles next to channel names by default. Use the control icons in the bottom-right to switch to a compact icon display, or deselect both to hide tags entirely.</p><h2 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to &quot;Statistics&quot;">​</a></h2><h3 id="current-vs-lifetime" tabindex="-1">Current vs. lifetime <a class="header-anchor" href="#current-vs-lifetime" aria-label="Permalink to &quot;Current vs. lifetime&quot;">​</a></h3><ul><li><strong>Current Statistics</strong>. Counts since the statistics were last reset. This is the default view.</li><li><strong>Lifetime Statistics</strong>. Cumulative totals across all deployments.</li></ul><p>Toggle between the two using the radio buttons at the bottom of the dashboard table.</p><h3 id="resetting-statistics" tabindex="-1">Resetting statistics <a class="header-anchor" href="#resetting-statistics" aria-label="Permalink to &quot;Resetting statistics&quot;">​</a></h3><ul><li><strong>Current statistics</strong>. Select the channel and click <strong>Clear Statistics</strong> in the task panel</li><li><strong>Lifetime statistics</strong>. Can be reset from the Server Settings tab</li></ul><h2 id="server-log" tabindex="-1">Server Log <a class="header-anchor" href="#server-log" aria-label="Permalink to &quot;Server Log&quot;">​</a></h2><p>The <strong>Server Log</strong> tab (below the dashboard table) mirrors the most recent entries from the server&#39;s log files. Each entry includes:</p><ul><li>A timestamp</li><li>A severity level: OFF, FATAL, ERROR, WARN, INFO, DEBUG, TRACE, or ALL</li><li>The originating class/category and line number (when available)</li><li>The log message itself</li></ul><p>Long messages are truncated in the table. Double-click an entry to see the full text in a separate window.</p><p>Controls:</p><ul><li><strong>Log Size</strong> (bottom-right). Adjust how many entries to keep in the tab (default 50). New entries push out the oldest.</li><li><strong>Start/Pause</strong> button (bottom-left). Freezes the log display so entries are not rotated out while you inspect them</li><li><strong>X</strong> button (bottom-left). Clears all entries currently displayed</li></ul><h2 id="connection-log" tabindex="-1">Connection log <a class="header-anchor" href="#connection-log" aria-label="Permalink to &quot;Connection log&quot;">​</a></h2><p>The <strong>Connection Log</strong> tab shows a real-time, event-by-event record of connector activity as messages flow through channels. Unlike the Server Log, the Connection Log is held only in memory and is not written to disk.</p><p>Columns include Timestamp, Channel, Connector Info, Event (e.g. Connected, Disconnected, Sending, Idle), and Info (which typically shows socket addresses for TCP-based connectors).</p><p>The default display limit is 250 entries, adjustable up to 999 via the <strong>Log Size</strong> control.</p><h2 id="global-maps" tabindex="-1">Global maps <a class="header-anchor" href="#global-maps" aria-label="Permalink to &quot;Global maps&quot;">​</a></h2><p>The <strong>Global Maps</strong> tab displays the current contents of the Global Map and Global Channel Maps.</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Server Id</strong></td><td>The server where the variable resides</td></tr><tr><td><strong>Channel</strong></td><td>The channel name, or <code>&lt;Global Map&gt;</code> for server-wide entries</td></tr><tr><td><strong>Key</strong></td><td>The variable name</td></tr><tr><td><strong>Value</strong></td><td>The current value (shown as its string representation). Double-click truncated values to see the full content.</td></tr></tbody></table><p>Select one or more channels in the dashboard table to see their channel-level map entries alongside the global ones.</p><h2 id="message-browser" tabindex="-1">Message Browser <a class="header-anchor" href="#message-browser" aria-label="Permalink to &quot;Message Browser&quot;">​</a></h2><p>Open the Message Browser by selecting a channel on the Dashboard and clicking <strong>View Messages</strong>, or by double-clicking the channel row. You can also reach it from the Channels view.</p><h3 id="metadata-table" tabindex="-1">Metadata table <a class="header-anchor" href="#metadata-table" aria-label="Permalink to &quot;Metadata table&quot;">​</a></h3><p>The top portion of the browser lists messages matching your search criteria. Messages are grouped by ID, with one row per connector message (source, each destination). Default columns include:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Id</strong></td><td>The unique message identifier within the channel</td></tr><tr><td><strong>Connector</strong></td><td>The connector name (e.g. &quot;Source&quot;, &quot;Destination 1&quot;)</td></tr><tr><td><strong>Status</strong></td><td>The connector message status (Received, Filtered, Transformed, Sent, Queued, Error, Pending)</td></tr><tr><td><strong>Received Date</strong></td><td>When the message was received by this connector</td></tr><tr><td><strong>Response Date</strong></td><td>When the response was recorded</td></tr><tr><td><strong>Errors</strong></td><td>Whether errors occurred: Processing, Response, Postprocessor, or Multiple</td></tr></tbody></table><p>Additional columns (Orig. Received Date, Send Attempts, Send Date, Server Id, Original Server Id, Original Id, Import Id, Import Channel Id, Channel Name) can be shown through the Column Options control. Channels with custom metadata columns will also display those columns.</p><h3 id="message-content" tabindex="-1">Message content <a class="header-anchor" href="#message-content" aria-label="Permalink to &quot;Message content&quot;">​</a></h3><p>Select a connector message and use the <strong>Messages</strong> tab below the table to view the message at different processing stages:</p><table tabindex="0"><thead><tr><th>Content Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Raw</strong></td><td>The original inbound message as stored after attachment extraction</td></tr><tr><td><strong>Processed Raw</strong></td><td>The message after the preprocessor script has modified it</td></tr><tr><td><strong>Transformed</strong></td><td>The internal (serialized) representation after the transformer has run</td></tr><tr><td><strong>Encoded</strong></td><td>The final output after deserialization into the outbound data type</td></tr><tr><td><strong>Sent</strong></td><td>The actual payload and connection properties captured just before dispatch (destination connectors only)</td></tr><tr><td><strong>Response</strong></td><td>The reply from the external system (or the generated acknowledgment)</td></tr><tr><td><strong>Response Transformed</strong></td><td>The serialized form of the response after the response transformer (destination connectors only)</td></tr><tr><td><strong>Processed Response</strong></td><td>The response in its final deserialized form (destination connectors only)</td></tr></tbody></table><p>Enable <strong>Format XML Messages</strong> to pretty-print XML and JSON content for easier reading. This affects only the display, not the stored data.</p><h3 id="mappings-tab" tabindex="-1">Mappings tab <a class="header-anchor" href="#mappings-tab" aria-label="Permalink to &quot;Mappings tab&quot;">​</a></h3><p>Shows all variable map entries (scope, variable name, and value) for the selected connector message. Double-click an entry to view long values in a popup.</p><h3 id="errors-tab" tabindex="-1">Errors tab <a class="header-anchor" href="#errors-tab" aria-label="Permalink to &quot;Errors tab&quot;">​</a></h3><p>When a connector message has error content, an <strong>Errors</strong> tab appears showing the error type (Processing Error, Response Error, etc.) along with the full stack trace.</p><h3 id="message-browser-tasks" tabindex="-1">Message Browser Tasks <a class="header-anchor" href="#message-browser-tasks" aria-label="Permalink to &quot;Message Browser Tasks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Reloads results within the current search window (preserves your page position and max message ID)</td></tr><tr><td><strong>Send Message</strong></td><td>Submit a test message to the current channel</td></tr><tr><td><strong>Import Messages</strong></td><td>Load previously exported XML message files into the channel&#39;s storage. Messages can be imported from the server filesystem or your local machine.</td></tr><tr><td><strong>Export Results</strong></td><td>Export all messages matching the current search to XML, with optional compression (ZIP, tar.gz, tar.bz2), encryption, and password protection</td></tr><tr><td><strong>Remove All Messages</strong></td><td>Delete all stored messages and attachments for this channel</td></tr><tr><td><strong>Remove Results</strong></td><td>Delete all messages matching the current search criteria (requires <code>REMOVEALL</code> confirmation)</td></tr><tr><td><strong>Remove Message</strong></td><td>Delete a single connector message. Removing a source message also removes all its destination messages.</td></tr><tr><td><strong>Reprocess Results</strong></td><td>Re-run all messages matching the current search through the channel (requires <code>REPROCESSALL</code> confirmation)</td></tr><tr><td><strong>Reprocess Message</strong></td><td>Re-run a single message, with the option to overwrite the existing message or create a new one, and to include or exclude specific destinations</td></tr><tr><td><strong>View Attachment</strong></td><td>View an attachment in the Administrator (only available when an attachment is selected)</td></tr><tr><td><strong>Export Attachment</strong></td><td>Save an attachment to disk as binary or Base64 text</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When reprocessing a message, two source map variables are injected: <code>reprocessed</code> (always <code>true</code>) and <code>replaced</code> (indicates whether the original message was overwritten).</p></div><h2 id="event-browser" tabindex="-1">Event Browser <a class="header-anchor" href="#event-browser" aria-label="Permalink to &quot;Event Browser&quot;">​</a></h2><p>Access the Event Browser by clicking <strong>Events</strong> in the main navigation. It provides a searchable audit trail of everything that happens on the server.</p><h3 id="event-table-columns" tabindex="-1">Event table columns <a class="header-anchor" href="#event-table-columns" aria-label="Permalink to &quot;Event table columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Level</strong></td><td>Severity icon: Information, Warning, or Error</td></tr><tr><td><strong>Date &amp; Time</strong></td><td>When the event was logged</td></tr><tr><td><strong>Name</strong></td><td>The operation name or a description of the warning/error</td></tr><tr><td><strong>Server ID</strong></td><td>Which server logged the event</td></tr><tr><td><strong>User</strong></td><td>The user who performed the action, or <code>0 (System)</code> for automated events</td></tr><tr><td><strong>Outcome</strong></td><td>Success or failure indicator</td></tr><tr><td><strong>IP Address</strong></td><td>The originating client IP for user-initiated actions</td></tr><tr><td><strong>Channel ID - Message ID</strong></td><td>The associated channel and message, if applicable</td></tr><tr><td><strong>Channel Name</strong></td><td>The associated channel name, if applicable</td></tr><tr><td><strong>Patient ID</strong></td><td>For Accessed PHI events, the patient identifier (requires a PATIENT_ID custom metadata column)</td></tr></tbody></table><h3 id="searching-events" tabindex="-1">Searching events <a class="header-anchor" href="#searching-events" aria-label="Permalink to &quot;Searching events&quot;">​</a></h3><p>Filter events by date range, name text, severity level (Information, Warning, Error), and advanced criteria including user, outcome, attribute values, IP address, and server ID.</p><h3 id="event-tasks" tabindex="-1">Event tasks <a class="header-anchor" href="#event-tasks" aria-label="Permalink to &quot;Event tasks&quot;">​</a></h3><ul><li><strong>Refresh</strong>. Reload within the current search (preserves page position)</li><li><strong>Export All Events</strong>. Write all events to a text file in the server&#39;s exports directory</li></ul><h3 id="phi-events" tabindex="-1">PHI events <a class="header-anchor" href="#phi-events" aria-label="Permalink to &quot;PHI events&quot;">​</a></h3><p>If a channel populates a custom metadata column named <code>PATIENT_ID</code>, the Event Browser will log <strong>Queried PHI</strong> events when users search that channel&#39;s messages, and <strong>Accessed PHI</strong> events when users view individual messages containing a patient ID.</p>',70)]))}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
